@Component("wallet-handler")
@ProcessingGroup("wallet-processing-group")
public class WalletEventHandler {
	
	// core constructor
	WalletEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateWalletEvent
     */
    @EventHandler
    public void handle( CreateWalletEvent event) {
        entityManager.persist(new Wallet(event.getWalletId(), event.getCurrency(), event.getBalance(), event.getCustomer(), event.getTransactions(), event.getStatus()));
    }

    /*
     * @param	event UpdateWalletEvent
     */
    @EventHandler
    public Wallet handle( UpdateWalletEvent event) {
    	entityManager.merge(new Wallet(event.getWalletId(), event.getCurrency(), event.getBalance(), event.getCustomer(), event.getTransactions(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteWalletEvent
     */
    @EventHandler
    public void on( DeleteWalletEvent event) {
    	Wallet entity = new Wallet();
   
    	// ------------------------------------------
    	// apply the WalletId
    	// ------------------------------------------
    	entity.setWalletId( event.getWalletId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final WalletRepository walletEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(WalletEventHandler.class.getName());

}
